function evenGapSplits(nums: number[]): number {
  const total = nums.reduce((a, b) => a + b, 0);
  let left = 0, count = 0;
  for (let i = 0; i < nums.length - 1; i++) {
    left += nums[i];
    if ((left - (total - left)) % 2 === 0) count++;
  }
  return count;
}

